window.AUTH=window.AUTH||{};window.AUTH["24-362"]={"d":"24-362","id":"2024/24-362","n":"Martin v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioners Curtrina Martin, et al.","date":"2025-03-07","url":"https://www.supremecourt.gov/DocketPDF/24/24-362/351456/20250307121332188_Martin%20v.%20United%20States%20Petitioners%20Merits%20Brief.pdf","side":"pet","n":75},{"k":"respondent","label":"Brief of respondents United States, et al.","date":"2025-04-01","url":"https://www.supremecourt.gov/DocketPDF/24/24-362/354570/20250401212308544_Martin_040125.2.pdf","side":"res","n":63},{"k":"reply","label":"Reply of petitioners Curtrina Martin, et al.","date":"2025-04-22","url":"https://www.supremecourt.gov/DocketPDF/24/24-362/356206/20250422120629032_Martin%20v.%20United%20States%20Petitioners%20Reply%20Brief.pdf","side":"pet","n":47}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/605us2r44_4f57.pdf","tr":true,"items":[{"t":"case","label":"Alaska v. United States","cite":"545 U.S. 75","y":2005,"id":"2004/128-orig","sc":1,"op":1,"ar":1,"sum":"The Court unanimously concluded that the Alexander Archipelago waters were not inland waters and thus belonged to the federal government.","sumSrc":"Oyez","by":{"0":"42","1":"26","2":"17–19"}},{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"43","1":"29, 34","2":"21"}},{"t":"case","label":"Association of Westinghouse Salaried Employees v. Westinghouse Electric Corp.","cite":"348 U.S. 437","y":1955,"id":"scdb/1954-044","sc":1,"sum":"The federal court did not have jurisdiction of the suit. Pp. 439-465. 210 F. 2d 623, affirmed. MR. JUSTICE FRANKFURTER, in an opinion joined by MR. JUSTICE BURTON and MR. JUSTICE MINTON, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Babb v. Wilkie","cite":"589 U.S. 399","y":2020,"id":"2019/18-882","sc":1,"sum":"The Court held that the federal-sector provision of the Age Discrimination in Employment Act of 1967 demands that personnel actions be untainted by any consideration of age, but but-for causation is important in determining the appropriate remedy that may be obtained.","sumSrc":"Oyez","by":{"0":"22","2":"10"}},{"t":"case","label":"Berkovitz v. United States","cite":"486 U.S. 531","y":1988,"id":"1987/87-498","sc":1,"op":3,"sum":"A provision of the Federal Tort Claims Act (FTCA) excepts from statutory liability any claim \"based upon [a federal agency's or employee's] exercise or performance or the failure to exercise or perform a discretionary function or duty.\" Upon contracting a severe case of polio after ingesting a dose of Orimune, an oral polio vaccine manufactured by Lederle Laboratories, petitioner Kevan Berkovitz, a minor, joined by …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 33, 35–36"}},{"t":"case","label":"Bivens v. Six Unknown Named Agents of Federal Bureau of Narcotics","cite":"403 U.S. 388","y":1971,"id":"1970/301","sc":1,"op":1,"sum":"The Supreme Court held that Bivens does have a cause of action for damages arising from the federal agents Fourth Amendment violations. Bivens must provide proof of his injuries in order to recover. The Court did not reach the privilege question because the Court of Appeals did not consider the question.","sumSrc":"Oyez","by":{"0":"4","1":"16"}},{"t":"case","label":"Brownback v. King","cite":"592 U.S. 209","y":2021,"id":"2020/19-546","sc":1,"op":2,"sum":"The District Court’s order dismissing King’s Federal Tort Claims Act claims was a judgment on the merits that can trigger the Act’s judgment bar to block his Bivens claims. See 28 U. S. C. §2676; Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"C.M. v. United States","cite":"672 F. Supp. 3d 288","y":2023,"court":"W.D. Tex.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/672/288/","sum":"Explaining that “neither cited Supreme Court case [in Shivers] uses ‘unless’ in that context”.","sumSrc":"brief:0","by":{"0":"36"}},{"t":"case","label":"Caban v. United States","cite":"671 F.2d 1230","y":1982,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/671/1230/","by":{"0":"38"}},{"t":"case","label":"Campos v. United States","cite":"888 F.3d 724","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/888/724/","by":{"0":"37"}},{"t":"case","label":"Carlson v. Green","cite":"446 U.S. 14","y":1980,"id":"1979/78-1261","sc":1,"op":1,"sum":"Respondent brought suit in Federal District Court in Indiana on behalf of her deceased son's estate, alleging that her son while a prisoner in a federal prison in Indiana suffered personal injuries from which he died because petitioner prison officials violated, inter alia, his Eighth Amendment rights by failing to give him proper medical attention. Asserting jurisdiction under 28 U. S. C. § 1331 (a), respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 9–10, 39","1":"37","2":"19, 23"}},{"t":"case","label":"Carter v. United States","cite":"604 U.S. ___","y":2025,"sc":1,"by":{"0":"36"}},{"t":"case","label":"Chadd v. United States","cite":"794 F.3d 1104","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/1104/","by":{"0":"44"}},{"t":"case","label":"Cope v. Cope","cite":"137 U.S. 682","y":1891,"id":"scdb/1890-084","sc":1,"sum":"The statute of Utah of 1852, (Compiled Laws of Utah, 1876, sec. 677,) which provides that “illegitimate children and their mothers inherit in like manner from the father, whether acknowledged by him or not, provided it shall be made to appearto the satisfaction of the court that he was the father of such illegitimate child or children,” was an act-of legislation within the powers conferred upon the Territorial …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23–24"}},{"t":"case","label":"Dalehite v. United States","cite":"346 U.S. 15","y":1953,"id":"scdb/1952-101","sc":1,"sum":"As a matter of law, the facts found by the District Court cannot give it jurisdiction of the cause under the Act, because the claim is \"based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the plirt of a federal agency or an employee of the Government,\" within the meaning of 28 U. S. C. § 2680 (a), which makes the Act inapplicable to such claims.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 27–28, 30–31, 50"}},{"t":"case","label":"Denson v. United States","cite":"574 F.3d 1318","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/574/1318/","op":3,"by":{"0":"5, 14–16, 47–50","1":"19, 48"}},{"t":"case","label":"Department of Commerce v. New York","cite":"588 U.S. 752","y":2019,"id":"2018/18-966","sc":1,"sum":"The Secretary did not violate the Enumeration Clause or the Census Act in deciding to reinstate a citizenship question on the 2020 census questionnaire, but the District Court was warranted in remanding the case back to the agency where the evidence tells a story that does not match the Secretary’s explanation for his decision.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43"}},{"t":"case","label":"Dolan v. USPS","cite":"546 U.S. 481","y":2006,"id":"2005/04-848","sc":1,"sum":"The Court ruled that the \"negligent transmission\" exception was inapplicable to Dolan's case, and therefore sovereign immunity had been waived and her case could proceed. The Court accepted Dolan's argument that the exception was only meant to encompass cases of late, missing, or incorrectly delivered mail.","sumSrc":"Oyez","by":{"0":"45","1":"9, 31, 39","2":"20"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"case","label":"Dykstra v. Bureau of Prisons","cite":"140 F.3d 791","y":1998,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/140/791/","by":{"0":"37"}},{"t":"case","label":"Eastern Air Lines, Inc. v. Union Trust Co.","cite":"221 F.2d 62","y":1955,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/221/62/","by":{"0":"29"}},{"t":"case","label":"Egbert v. Boule","cite":"596 U.S. 482","y":2022,"id":"2021/21-147","sc":1,"sum":"The authority of a court to imply a cause of action under Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388, does not extend to either Boule’s Fourth Amendment excessive-force claim or his First Amendment retaliation claim.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4","2":"23"}},{"t":"case","label":"Esquivel v. United States","cite":"21 F.4th 565","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/21/565/","by":{"0":"37"}},{"t":"case","label":"FDIC v. Meyer","cite":"510 U.S. 471","y":1994,"id":"1993/92-741","sc":1,"sum":"After the Federal Savings and Loan Insurance Corporation (FSLIC), as receiver for a failing thrift institution, terminated respondent Meyer from his job as a senior officer of that institution, he filed this suit in the District Court, claiming that his summary discharge deprived him of a property right without due process of law in violation of the Fifth Amendment. In making this claim, he relied on Bivens v. Six …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"6","1":"8, 47","2":"11–12, 20"}},{"t":"case","label":"Feres v. United States","cite":"340 U.S. 135","y":1950,"id":"scdb/1950-013","sc":1,"by":{"0":"5–6"}},{"t":"case","label":"Fischer v. United States","cite":"603 U.S. 480","y":2024,"id":"2023/23-5572","sc":1,"sum":"The Court held that 18 U.S.C. § 1512(c), which prohibits obstruction of congressional inquiries and investigations, does not include acts unrelated to investigations and evidence.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Garcia v. United States","cite":"826 F.2d 806","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/826/806/","by":{"0":"38–39"}},{"t":"case","label":"Gray v. Bell","cite":"712 F.2d 490","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/712/490/","op":1,"by":{"0":"38","1":"25"}},{"t":"case","label":"Hatahley v. United States","cite":"351 U.S. 173","y":1956,"id":"1955/231","sc":1,"sum":"On the record in this case, petitioners are entitled to a judgment for damages, which must be apportioned among them; but they are not entitled to an injunction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 32–34","2":"9"}},{"t":"case","label":"Indian Towing Co. v. United States","cite":"350 U.S. 61","y":1955,"id":"1955/8","sc":1,"sum":"If the Coast Guard is negligent in the operation of a lighthouse and damage is caused thereby, the United States is liable under the Tort Claims Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 50–51","2":"9, 11"}},{"t":"case","label":"Kordash v. United States","cite":"51 F.4th 1289","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/51/1289/","op":2,"by":{"0":"14–15, 48","1":"19","2":"3"}},{"t":"case","label":"Kosak v. United States","cite":"465 U.S. 848","y":1984,"id":"1983/82-618","sc":1,"sum":"Section 2680(c) precludes recovery against the United States for the alleged injury to petitioner's property.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24, 35"}},{"t":"case","label":"Levin v. United States","cite":"568 U.S. 503","y":2013,"id":"2012/11-1351","sc":1,"sum":"The Court held that the Gonzalez Act made an exception to the Federal Tort Claims Act by saying that a claim of the intentional tort of battery may be brought against an armed forces physician.","sumSrc":"Oyez","by":{"0":"7–8","1":"10, 11"}},{"t":"case","label":"Linder v. United States","cite":"937 F.3d 1087","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/1087/","ar":1,"by":{"0":"38","1":"25, 33, 36","2":"12"}},{"t":"case","label":"Martin v. United States","cite":"2022 WL 18263039","y":2022,"court":"N.D. Ga. Dec. 30","by":{"0":"1, 15, 48"}},{"t":"case","label":"Martin v. United States","cite":"2024 WL 1716235","y":2024,"court":"11th Cir. Apr. 22","op":1,"by":{"0":"1, 11–13, 15–16"}},{"t":"case","label":"Martin v. United States","cite":"631 F. Supp. 3d 1281","y":2022,"court":"N.D. Ga.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/631/1281/","op":2,"by":{"0":"1, 11–14, 34"}},{"t":"case","label":"Medina v. United States","cite":"259 F.3d 220","y":2001,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/259/220/","by":{"0":"37–38","1":"25"}},{"t":"case","label":"Millbrook v. United States","cite":"569 U.S. 50","y":2013,"id":"2012/11-10362","sc":1,"op":1,"sum":"The Court held that claims against the United States for the intentional torts of prison officials is not limited to violations made during searches, seizures, or arrests.","sumSrc":"Oyez","by":{"0":"10, 21, 38, 43","1":"11, 31"}},{"t":"case","label":"Molzof v. United States","cite":"502 U.S. 301","y":1992,"id":"1991/90-838","sc":1,"sum":"The District Court awarded the guardian ad litem of petitioner Molzof's since-deceased husband damages under the Federal Tort Claims Act (FTCA or Act) for supplemental medical care for injuries suffered by Mr. Molzof as a result of the negligence of federal employees, but refused to award damages for future medical expenses and for loss of enjoyment of life. The Court of Appeals affirmed, ruling that damages of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"5, 9","2":"20"}},{"t":"case","label":"Moor v. County of Alameda","cite":"411 U.S. 693","y":1973,"id":"1972/72-10","sc":1,"sum":"Petitioners Moor and Rundle. brought damages actions in the District Court against respondents, several law enforcement officers and Alameda County. Against the County they alleged federal causes of action under the Civil Rights Act of 1871, 42 U. S. C. §§ 1983 and 1988, and pendent state claims under the state tort claims statute, the federal, as well as the state, causes of action being grounded on the theory that …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"49"}},{"t":"case","label":"Nguyen v. United States","cite":"556 F.3d 1244","y":2009,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/556/1244/","op":2,"ar":3,"sum":"Holding that, where “the [law-enforcement] proviso applies to waive sovereign immunity, the [discretionary-function exception] is of no effect”.","sumSrc":"brief:0","by":{"0":"5, 13, 38, 40–41, 47, 50","1":"18, 31","2":"6, 21"}},{"t":"case","label":"Pennington v. United States","cite":"48 Ct. Cl. 408","y":1913,"url":"https://www.courtlistener.com/c/Ct.%20Cl./48/408/","by":{"0":"42"}},{"t":"case","label":"POM Wonderful LLC v. Coca-Cola Co.","cite":"573 U.S. 102","y":2014,"id":"2013/12-761","sc":1,"sum":"The Court held that it is the duty of the court system to harmonize statutes, and that barring one applicable statute by use of another represents a disregard of the law's intent of having cooperative statutes.","sumSrc":"Oyez","by":{"0":"44–45"}},{"t":"case","label":"Pooler v. United States","cite":"787 F.2d 868","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/787/868/","by":{"0":"38"}},{"t":"case","label":"RadLAX Gateway Hotel, LLC v. Amalgamated Bank","cite":"566 U.S. 639","y":2012,"id":"2011/11-166","sc":1,"sum":"The Court held that a company could not obtain confirmation of a Chapter 11 bankruptcy plan that provided for the sale of its assets free from lien without permitting a bank to credit-bid at the sale.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"Rayonier Inc. v. United States","cite":"352 U.S. 315","y":1957,"id":"1956/45","sc":1,"sum":"Under the Federal Tort Claims Act, the United States is not immune from liability for negligence of employees of the Forest Service in fighting a fire, if in similar circumstances a private person would be liable under the laws of the State in which the fire occurred. Pp. 315-321. 225 F. 2d 642, 650, judgments vacated and causes remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28, 51","2":"15"}},{"t":"case","label":"Richards v. United States","cite":"369 U.S. 1","y":1962,"id":"1961/59","sc":1,"ar":1,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","2":"4"}},{"t":"case","label":"Shivers v. United States","cite":"1 F.4th 924","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/1/924/","op":3,"ar":1,"sum":"Rejecting a “constitutional-claims exclusion” to the discretionary function exception.","sumSrc":"brief:1","by":{"0":"15, 36","1":"36","2":"12"}},{"t":"case","label":"Simmons v. Himmelreich","cite":"578 U.S. 621","y":2016,"id":"2015/15-109","sc":1,"sum":"The Court determined that the judgment bar of the Federal Tort Claims Act (FTCA) does not apply to claims dismissed for falling under the exceptions to the FTCA.","sumSrc":"Oyez","by":{"0":"43, 45","2":"8"}},{"t":"case","label":"Sutton v. United States","cite":"819 F.2d 1289","y":1987,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/1289/","by":{"0":"39"}},{"t":"case","label":"Tennessee Wine & Spirits Retailers Ass’n v. Thomas","cite":"588 U.S. 504","y":2019,"id":"2018/18-96","sc":1,"sum":"Tennessee’s 2-year durational-residency requirement applicable to retail liquor store license applicants violates the Commerce Clause and is not saved by the Twenty-first Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44"}},{"t":"case","label":"Thacker v. TVA","cite":"587 U.S. 218","y":2019,"url":"https://supreme.justia.com/cases/federal/us/587/218/","sc":1,"op":1,"by":{"0":"45, 48–49"}},{"t":"case","label":"United States v. Aetna Casualty & Surety Co.","cite":"338 U.S. 366","y":1949,"id":"scdb/1949-019","sc":1,"sum":"Notwithstanding R. S. § 3477, restricting assignments of claims against the United States, an insurance company may bring an action under the Federal Tort Claims Act in its own name against the United States upon a claim to which it has become subrogated by payment to an insured who would have been able to bring such action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"United States v. Gaubert","cite":"499 U.S. 315","y":1991,"id":"1990/89-1793","sc":1,"op":8,"ar":11,"sum":"When the events in this case occurred, the Home Owners' Loan Act of 1933 authorized the Federal Home Loan Bank Board (FHLBB) to prescribe rules and regulations providing '\"for the organization, incorporation, examination, and regulation\" of federal savings and loan associations, and to issue charters, \"giving primary consideration to the best practices of thrift institutions in the United States.\" 12 U. S. C. § …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"7, 29–36","1":"10, 23, 30, 36, 41, 42, 44-46","2":"3, 9–11, 13, 20"}},{"t":"case","label":"United States v. Neustadt","cite":"366 U.S. 696","y":1961,"id":"1960/533","sc":1,"sum":"Under the Federal Tort Claims Act, the United States may not be held liable to a purchaser of a home who has been furnished a statement reporting the results of a negligently inaccurate inspection and appraisal of the property made by the Federal Housing Administration for mortgage insurance purposes pursuant to the National Housing Act of 1934, as amended, and who, in reliance upon such statement, has been induced …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8"}},{"t":"case","label":"United States v. Shearer","cite":"473 U.S. 52","y":1985,"id":"1984/84-194","sc":1,"sum":"Recovery under the Act is barred by the Feres doctrine, which is based, inter alia, on the special relationship of the soldier to his superiors, the effects of the maintenance of suits under the Act on discipline, and the extreme results that might obtain if such suits were allowed for negligent orders given or negligent acts committed in the course of military duty. The Court of Appeals erroneously placed great …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 20–21","2":"15"}},{"t":"case","label":"United States v. United States Trust Co.","cite":"350 U.S. 907","y":1955,"url":"https://supreme.justia.com/cases/federal/us/350/907/","sc":1,"by":{"0":"29"}},{"t":"case","label":"United States v. Varig Airlines","cite":"467 U.S. 797","y":1984,"id":"1983/82-1349","sc":1,"op":1,"sum":"Government liability under the FTCA is limited by the discretionary function exception of 28 U.S.C. Section 2680(a), which provides that the federal government may not be held liable for \"[a]ny claim based upon an act or omission of an employee of the Government . . . based upon the exercise or performance or the failure to exercise or perform a discretionary function . . . whether or not the discretion involved be abused.\" The FAA's decision to institute the \"spot-check\" program to monitor compliance with its minimum safety standards was clearly discretionary and protected by Section 2680(a).","sumSrc":"Oyez","by":{"0":"17, 20, 29–30, 34","1":"10","2":"6"}},{"t":"case","label":"United States v. Yellow Cab Co.","cite":"340 U.S. 543","y":1951,"id":"scdb/1950-045","sc":1,"sum":"The Federal Tort Claims Act empowers a United States District Court to require the United States to be impleaded as a thirdparty defendant and to answer the claim of a joint tort-feasor for contribution as if the United States were a private individual.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35","2":"20"}},{"t":"case","label":"Vasquez v. Smith","cite":"576 S.E.2d 59","y":2003,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/576/59/","by":{"0":"33–34"}},{"t":"case","label":"West Virginia v. EPA","cite":"597 U.S. 697","y":2022,"url":"https://supreme.justia.com/cases/federal/us/597/697/","sc":1,"by":{"0":"36"}},{"t":"case","label":"Xi v. Haugen","cite":"68 F.4th 824","y":2023,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/68/824/","op":4,"by":{"0":"21, 25, 36, 38","2":"12"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(b)(1)","(b)"],"stext":{"head":"§1346. United States as defendant","paras":[[0,"(a) The district courts shall have original jurisdiction, concurrent with the United States Court of Federal Claims, of:"],[1,"(1) Any civil action against the United States for the recovery of any internal-revenue tax alleged to have been erroneously or illegally assessed or collected, or any penalty claimed to have been collected without authority or any sum alleged to have been excessive or in any manner wrongfully collected under the internal-revenue laws;"],[1,"(2) Any other civil action or claim against the United States, not exceeding $10,000 in amount, founded either upon the Constitution, or any Act of Congress, or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort, except that the district courts shall not have jurisdiction of any civil action or claim against the United States founded upon any express or implied contract with the United States or for liquidated or unliquidated damages in cases not sounding in tort which are subject to sections 7104(b)(1) and 7107(a)(1) of title 41. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(b)(1) Subject to the provisions of chapter 171 of this title, the district courts, together with the United States District Court for the District of the Canal Zone and the District Court of the Virgin Islands, shall have exclusive jurisdiction of civil actions on claims against the United States, for money damages, accruing on and after January 1, 1945, for injury or loss of property, or personal injury or death caused by the negligent or wrongful act or omission of any employee of the Government while acting within the scope of his office or employment, under circumstances where the United States, if a private person, would be liable to the claimant in accordance with the law of the place where the act or omission occurred."],[0,"(2) No person convicted of a felony who is incarcerated while awaiting sentencing or while serving a sentence may bring a civil action against the United States or an agency, officer, or employee of the Government, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(c) The jurisdiction conferred by this section includes jurisdiction of any set-off, counterclaim, or other claim or demand whatever on the part of the United States against any plaintiff commencing an action under this section."],[0,"(d) The district courts shall not have jurisdiction under this section of any civil action or claim for a pension."],[0,"(e) The district courts shall have original jurisdiction of any civil action against the United States provided in section 6226, 6228(a), 7426, or 7428 (in the case of the United States district court for the District of Columbia) or section 7429 of the Internal Revenue Code of 1986."],[0,"(f) The district courts shall have exclusive original jurisdiction of civil actions under section 2409a to quiet title to an estate or interest in real property in which an interest is claimed by the United States."],[0,"(g) Subject to the provisions of chapter 179, the district courts of the United States shall have exclusive jurisdiction over any civil action commenced under section 453(2) of title 3, by a covered employee under chapter 5 of such title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1346?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1346. United States as defendant","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 6, 19, 33, 48, 50","1":"5, 8, 2, 8, 30, 43, 48","2":"12–13"}},{"t":"usc","label":"28 U.S.C. § 2674","url":"https://www.law.cornell.edu/uscode/text/28/2674","stext":{"head":"§2674. Liability of United States","paras":[[0,"The United States shall be liable, respecting the provisions of this title relating to tort claims, in the same manner and to the same extent as a private individual under like circumstances, but shall not be liable for interest prior to judgment or for punitive damages."],[0,"If, however, in any case wherein death was caused, the law of the place where the act or omission complained of occurred provides, or has been construed to provide, for damages only punitive in nature, the United States shall be liable for actual or compensatory damages, measured by the pecuniary injuries resulting from such death to the persons respectively, for whose benefit the action was brought, in lieu thereof."],[0,"With respect to any claim under this chapter, the United States shall be entitled to assert any defense based upon judicial or legislative immunity which otherwise would have been available to the employee of the United States whose act or omission gave rise to the claim, as well as any other defenses to which the United States is entitled."],[0,"With respect to any claim to which this section applies, the Tennessee Valley Authority shall be entitled to assert any defense which otherwise would have been available to the employee based upon judicial or legislative immunity, which otherwise would have been available to the employee of the Tennessee Valley Authority whose act or omission gave rise to the claim as well as any other defenses to which the Tennessee Valley Authority is entitled under this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2674?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":3,"head":"§2674. Liability of United States","tname":"Judiciary and Judicial Procedure","by":{"0":"6","1":"8","2":"4, 11"}},{"t":"usc","label":"28 U.S.C. § 2676","url":"https://www.law.cornell.edu/uscode/text/28/2676","by":{"0":"45"}},{"t":"usc","label":"28 U.S.C. § 2680","url":"https://www.law.cornell.edu/uscode/text/28/2680","subs":["(a)","(h)","(b)","(c)","(k)"],"stext":{"head":"§2680. Exceptions","paras":[[0,"The provisions of this chapter and section 1346(b) of this title shall not apply to—"],[0,"(a) Any claim based upon an act or omission of an employee of the Government, exercising due care, in the execution of a statute or regulation, whether or not such statute or regulation be valid, or based upon the exercise or performance or the failure to exercise or perform a discretionary function or duty on the part of a federal agency or an employee of the Government, whether or not the discretion involved be abused."],[0,"(b) Any claim arising out of the loss, miscarriage, or negligent transmission of letters or postal matter."],[0,"(c) Any claim arising in respect of the assessment or collection of any tax or customs duty, or the detention of any goods, merchandise, or other property by any officer of customs or excise or any other law enforcement officer, except that the provisions of this chapter and section 1346(b) of this title apply to any claim based on injury or loss of goods, merchandise, or other property, while in the possession of any officer of customs or excise or any other law enforcement officer, if—"],[1,"(1) the property was seized for the purpose of forfeiture under any provision of Federal law providing for the forfeiture of property other than as a sentence imposed upon conviction of a criminal offense;"],[1,"(2) the interest of the claimant was not forfeited;"],[1,"(3) the interest of the claimant was not remitted or mitigated (if the property was subject to forfeiture); and"],[1,"(4) the claimant was not convicted of a crime for which the interest of the claimant in the property was subject to forfeiture under a Federal criminal forfeiture law..1"],[0,"(d) Any claim for which a remedy is provided by chapter 309 or 311 of title 46 relating to claims or suits in admiralty against the United States."],[0,"(e) Any claim arising out of an act or omission of any employee of the Government in administering the provisions of sections 1–31 of Title 50, Appendix.2"],[0,"(f) Any claim for damages caused by the imposition or establishment of a quarantine by the United States."],[0,"[(g) Repealed. Sept. 26, 1950, ch. 1049, §13 (5), 64 Stat. 1043.]"],[0,"(h) Any claim arising out of assault, battery, false imprisonment, false arrest, malicious prosecution, abuse of process, libel, slander, misrepresentation, deceit, or interference with contract rights: Provided, That, with regard to acts or omissions of investigative or law enforcement officers of the United States Government, the provisions of this chapter and section 1346(b) of this title shall apply to any claim arising, on or after the date of the enactment of this proviso, out of assault, battery, false imprisonment, false arrest, abuse of process, or malicious prosecution. For the purpose of this subsection, \"investigative or law enforcement officer\" means any officer of the United States who is empowered by law to execute searches, to seize evidence, or to make arrests for violations of Federal law."],[0,"(i) Any claim for damages caused by the fiscal operations of the Treasury or by the regulation of the monetary system."],[0,"(j) Any claim arising out of the combatant activities of the military or naval forces, or the Coast Guard, during time of war."],[0,"(k) Any claim arising in a foreign country."],[0,"(l) Any claim arising from the activities of the Tennessee Valley Authority."],[0,"(m) Any claim arising from the activities of the Panama Canal Company."],[0,"(n) Any claim arising from the activities of a Federal land bank, a Federal intermediate credit bank, or a bank for cooperatives."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2680?type=usc&year=mostrecent&link-type=html"},"op":14,"ar":2,"head":"§2680. Exceptions","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 42, 2, 4, 7, 13, 19, 24–26, 40, 3–4, 7–10, 19–23, 40–43","1":"2, 6, 8-10, 18, 21, 22, 24, 25, 28, 31, 33, 10, 32, 33, 36, 44, 10, 29, 32-34, 10, 11, 12, 18, 21, 22, 27, 29, 32-34, 41, 42, 10, 10, 30","2":"1, 21, 11, 15, 8"}},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","subs":["(d)"],"by":{"0":"27"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","subs":["(a)(2)"],"by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 93-253","url":"https://www.govinfo.gov/link/statute/88/50","by":{"0":"9","1":"11, 27"}},{"t":"case","label":"Anderson v. Creighton","cite":"483 U.S. 635","y":1987,"id":"1986/85-1520","sc":1,"sum":"The Court held that an officer of the law has qualified immunity from civil liability if the actions that officer took “could reasonably have been thought consistent” with the allegedly violated rights. Because Anderson could reasonably believe that his actions were legal, he is entitled to qualified immunity.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Asgrow Seed Co. v. Winterboer","cite":"513 U.S. 179","y":1995,"id":"1994/92-2038","sc":1,"sum":"The Court held that a farmer may sell for reproductive purposes only such seed as he has saved for the purpose of replanting his own fields. While the statute allows farmers to save seed to replant and then sell that saved seed to other farmers for planting, the statute prohibits growing protected seed as a \"step in marketing\" it as seed for planting.","sumSrc":"Oyez","by":{"1":"27, 28"}},{"t":"case","label":"Askew v. Bloemker","cite":"548 F.2d 673","y":1976,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/548/673/","op":1,"by":{"1":"35"}},{"t":"case","label":"Cyan, Inc. v. Beaver Cnty. Employees Ret. Fund","cite":"583 U.S. 416","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Department of Agric. Rural Dev. Rural Hous. Serv. v. Kirtz","cite":"601 U.S. 42","y":2024,"id":"2023/22-846","sc":1,"sum":"A consumer may sue a federal agency under 15 U. S. C. §§1681n and 1681o for defying the terms of the Fair Credit Reporting Act.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"7, 35"}},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"op":1,"sum":"The Court held that the Federal Arbitration Act requires that arbitration agreements providing for individualized proceedings be enforced.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"592 U.S. 395","y":2021,"id":"2020/19-511","sc":1,"op":1,"sum":"To qualify as an “automatic telephone dialing system” under the Telephone Consumer Protection Act of 1991, a device must have the capacity either to store, or to produce, a telephone number using a random or sequential number generator.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Foley v. Connelie","cite":"435 U.S. 291","y":1978,"id":"1977/76-839","sc":1,"sum":"In a 6-to-3 decision, the Court held that the states had an \"historical power to exclude aliens from participation in its democratic political institutions\" and that the New York statute did not violate the Equal Protection Clause.","sumSrc":"Oyez","by":{"1":"31, 42, 43"}},{"t":"case","label":"Food Mktg. Inst. v. Argus Leader Media","cite":"588 U.S. 427","y":2019,"id":"2018/18-481","sc":1,"sum":"Where commercial or financial information is both customarily and actually treated as private by its owner and provided to the government under an assurance of privacy, the information is “confidential” within the meaning of 5 U. S. C. §552(b)(4), the Freedom of Information Act’s Exemption 4.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"35"}},{"t":"case","label":"Gasho v. United States","cite":"39 F.3d 1420","y":1994,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/39/1420/","by":{"1":"25"}},{"t":"case","label":"Graham v. Connor","cite":"490 U.S. 386","y":1989,"id":"1988/87-6571","sc":1,"sum":"In a unanimous ruling written by Justice William Rehnquist, the Court held that claims of excessive force used by government officials are properly analyzed under the Fourth Amendment’s “objective reasonableness” standard. The Court vacated the directed verdict and remanded the case to the district court to be decided by that standard.","sumSrc":"Oyez","by":{"1":"42","2":"15"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"1":"37","2":"11"}},{"t":"case","label":"Hatzlachh Supply Co. v. United States","cite":"444 U.S. 460","y":1980,"id":"1979/78-1175","sc":1,"sum":"The United States may be held liable in an action under the Tucker Act for breach of an implied contract of bailment when goods are lost while held by the United States Customs Service following their seizure for customs violations.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Jama v. Immigration & Customs Enforcement","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"op":2,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"28, 32"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Joiner v. United States","cite":"955 F.3d 399","y":2020,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/955/399/","by":{"1":"25"}},{"t":"case","label":"Lane v. Pena","cite":"518 U.S. 187","y":1996,"id":"1995/95-365","sc":1,"op":3,"sum":"Although the related provisions of the 1973 Rehabilitation Act and the 1991 Civil Rights Act might in combination be read as waiving the federal government's sovereign immunity, absent an unambiguous waiver of sovereign immunity, the court cannot permit damages to be awarded.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Pulsifer v. United States","cite":"601 U.S. 124","y":2024,"id":"2023/22-340","sc":1,"sum":"A criminal defendant facing a mandatory minimum sentence is eligible for safety-valve relief under 18 U. S. C. §3553(f)(1) only if the defendant satisfies each of the provision’s three conditions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32"}},{"t":"case","label":"Radzanower v. Touche Ross & Co.","cite":"426 U.S. 148","y":1976,"id":"1975/75-268","sc":1,"sum":"Venue in a suit against a national banking association charged with violating the Securities Exchange Act of 1934 held to be governed by the venue provision of the National Bank Act, 12 U. S. C. § 94, which provides that an action against a national banking association may be had in any federal district court within the district in which such association may be established, rather than by § 27 of the Securities …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"37"}},{"t":"case","label":"Sosa v. Alvarez-Machain","cite":"542 U.S. 692","y":2004,"id":"2003/03-339","sc":1,"sum":"No and No. On the Alien Tort Statute claim, the Court unanimously ruled that the ATS did not create a separate ground of suit for violations of the law of nations. Instead, it was intended only to give courts jurisdiction over traditional law of nations cases - those involving ambassadors, for example, or piracy.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"United States v. Morrow","cite":"266 U.S. 531","y":1925,"id":"scdb/1924-070","sc":1,"op":1,"sum":"Mr, Merrill E. Otis, Special Assistant to the Attorney General, with whom Mr. Solicitor General Beck and Mr. John G. Ewing were on the brief, /or the Ünited States.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"26, 38"}},{"t":"case","label":"United States v. Olson","cite":"546 U.S. 43","y":2005,"id":"2005/04-759","sc":1,"op":2,"sum":"The Court held that the United States waived sovereign immunity only where local law would make a \"private person\" liable in tort, not where local law would make a \"state or municipal entity\" liable.","sumSrc":"Oyez","by":{"1":"8, 43"}},{"t":"case","label":"United States v. Orleans","cite":"425 U.S. 807","y":1976,"id":"1975/75-328","sc":1,"sum":"The Council and the Center are not federal agencies or instrumentalities and their employees are not federal employees within the meaning of the FTCA.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"8"}},{"t":"case","label":"United States v. Spelar","cite":"338 U.S. 217","y":1949,"id":"scdb/1949-001","sc":1,"sum":"The Federal Tort Claims Act, which is inapplicable by its terms to any claim \"arising in a foreign country,\" does not authorize an action against the United States for an allegedly wrongful death occurring at a Newfoundland air base under long-term lease from Great Britain to the United States and allegedly resulting from the negligent operation of the air base by the United States. VermilyaBrown Co. v. Connell, 335 …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Warner Chappell Music, Inc. v. Nealy","cite":"601 U.S. 366","y":2024,"id":"2023/22-1078","sc":1,"sum":"The Copyright Act entitles a copyright owner to obtain monetary relief for any timely infringement claim, no matter when the infringement occurred.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40, 41"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"16, 19, 36, 37"}},{"t":"usc","label":"18 U.S.C. § 3052","url":"https://www.law.cornell.edu/uscode/text/18/3052","by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 3107","url":"https://www.law.cornell.edu/uscode/text/18/3107","by":{"1":"42"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","subs":["(a)(2)(F)(ii)(II)"],"stext":{"head":"§1383. Procedure for payment of benefits","paras":[[0,"(a) Time, manner, form, and duration of payments; representative payees; promulgation of regulations"],[0,"(1) Benefits under this subchapter shall be paid at such time or times and (subject to paragraph (10)) in such installments as will best effectuate the purposes of this subchapter, as determined under regulations (and may in any case be paid less frequently than monthly where the amount of the monthly benefit would not exceed $10)."],[0,"(2)(A)(i) Payments of the benefit of any individual may be made to any such individual or to the eligible spouse (if any) of such individual or partly to each."],[0,"(ii)(I) Upon a determination by the Commissioner of Social Security that the interest of such individual would be served thereby, such payments shall be made, regardless of the legal competency or incompetency of the individual or eligible spouse, to another individual, or an organization, with respect to whom the requirements of subparagraph (B) have been met (in this paragraph referred to as such individual's \"representative payee\") for the use and benefit of the individual or eligible spouse."],[0,"(II) In the case of an individual eligible for benefits under this subchapter by reason of disability, the payment of such benefits shall be made to a representative payee if the Commissioner of Social Security determines that such payment would serve the interest of the individual because the individual also has an alcoholism or drug addiction condition (as determined by the Commissioner) and the individual is incapable of managing such benefits."],[0,"(iii) If the Commissioner of Social Security or a court of competent jurisdiction determines that the representative payee of an individual or eligible spouse has misused any benefits which have been paid to the representative payee pursuant to clause (ii) or section 405(j)(1) or 1007 of this title, the Commissioner of Social Security shall promptly terminate payment of benefits to the representative payee pursuant to this subparagraph, and provide for payment of benefits to an alternative representative payee of the individual or eligible spouse or, if the interest of the individual under this subchapter would be served thereby, to the individual or eligible spouse."],[0,"(iv) For purposes of this paragraph, misuse of benefits by a representative payee occurs in any case in which the representative payee receives payment under this subchapter for the use and benefit of another person and converts such payment, or any part thereof, to a use other than for the use and benefit of such other person. The Commissioner of Social Security may prescribe by regulation the meaning of the term \"use and benefit\" for purposes of this clause."],[0,"(B)(i) Any determination made under subparagraph (A) for payment of benefits to the representative payee of an individual or eligible spouse shall be made on the basis of—"],[1,"(I) an investigation by the Commissioner of Social Security of the person to serve as representative payee, which shall be conducted in advance of such payment, and shall, to the extent practicable, include a face-to-face interview with such person; and"],[1,"(II) adequate evidence that such payment is in the interest of the individual or eligible spouse (as determined by the Commissioner of Social Security in regulations)."],[0,"(ii) As part of the investigation referred to in clause (i)(I), the Commissioner of Social Security shall—"],[1,"(I) require the person being investigated to submit documented proof of the identity of such person, unless information establishing such identity was submitted with an application for benefits under subchapter II, subchapter VIII, or this subchapter;"],[1,"(II) verify the social security account number (or employer identification number) of such person;"],[1,"(III) determine whether such person has been convicted of a violation of section 408, 1011, or 1383a of this title;"],[1,"(IV) obtain information concerning whether the person has been convicted of any other offense under Federal or State law which resulted in imprisonment for more than 1 year;"],[1,"(V) obtain information concerning whether such person is a person described in section 1382(e)(4)(A) of this title;"],[1,"(VI) determine whether payment of benefits to such person has been terminated pursuant to subparagraph (A)(iii), whether the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, and whether certification of payment of benefits to such person has been revoked pursuant to section 405(j) of this title, by reason of misuse of funds paid as benefits under subchapter II, subchapter VIII, or this subchapter, and"],[1,"(VII) determine whether such person has been convicted (and not subsequently exonerated), under Federal or State law, of a felony provided under clause (xv), or of an attempt or a conspiracy to commit such a felony."],[0,"(iii) Benefits of an individual may not be paid to any other person pursuant to subparagraph (A)(ii) if—"],[1,"(I) such person has previously been convicted as described in clause (ii)(III);"],[1,"(II) except as provided in clause (iv), payment of benefits to such person pursuant to subparagraph (A)(ii) has previously been terminated as described in clause (ii)(VI), the designation of such person as a representative payee has been revoked pursuant to section 1007(a) of this title, or certification of payment of benefits to such person under section 405(j) of this title has previously been revoked as described in section 405(j)(2)(B)(i)(VI) of this title;"],[1,"(III) except as provided in clause (v), such person is a creditor of such individual who provides such individual with goods or services for consideration;"],[1,"(IV) the person has previously been convicted as described in clause (ii)(IV) of this subparagraph, unless the Commissioner determines that the payment would be appropriate notwithstanding the conviction;"],[1,"(V) such person is a person described in section 1382(e)(4)(A) of this title,"],[1,"(VI) except as provided in clause (xvii), such person has previously been convicted (and not subsequently exonerated) as described in clause (ii)(VII), or"],[1,"(VII) such person's benefits under this subchapter, subchapter II, or subchapter VIII are certified for payment to a representative payee during the period for which the individual's benefits would be certified for payment to another person."],[0,"(iv) The Commissioner of Social Security shall prescribe regulations under which the Commissioner of Social Security may grant an exemption from clause (iii)(II) to any person on a case-by-case basis if such exemption would be in the best interest of the individual or eligible spouse whose benefits under this subchapter would be paid to such person pursuant to subparagraph (A)(ii)."],[0,"(v) Clause (iii)(III) shall not apply with respect to any person who is a creditor referred to therein if such creditor is—"],[1,"(I) a relative of such individual if such relative resides in the same household as such individual;"],[1,"(II) a legal guardian or legal representative of such individual;"],[1,"(III) a facility that is licensed or certified as a care facility under the law of a State or a political subdivision of a State;"],[1,"(IV) a person who is an administrator, owner, or employee of a facility referred to in subclause (III) if such individual resides in such facility, and the payment of benefits under this subchapter to such facility or such person is made only after good faith efforts have been made by the local servicing office of the Social Security Administration to locate an alternative representative payee to whom the payment of such benefits would serve the best interests of such individual; or"],[1,"(V) an individual who is determined by the Commissioner of Social Security, on the basis of written findings and under procedures which the Commissioner of Social Security shall prescribe by regulation, to be acceptable to serve as a representative payee."],[0,"(vi) The procedures referred to in clause (v)(V) shall require the individual who will serve as representative payee to establish, to the satisfaction of the Commissioner of Social Security, that—"],[1,"(I) such individual poses no risk to the beneficiary;"],[1,"(II) the financial relationship of such individual to the beneficiary poses no substantial conflict of interest; and"],[1,"(III) no other more suitable representative payee can be found."],[0,"(vii) In the case of an individual described in subparagraph (A)(ii)(II), when selecting such individual's representative payee, preference shall be given to—"],[1,"(I) a certified community-based nonprofit social service agency (as defined in subparagraph (I));"],[1,"(II) a Federal, State, or local government agency whose mission is to carry out income maintenance, social service, or health care-related activities;"],[1,"(III) a State or local government agency with fiduciary responsibilities; or"],[1,"(IV) a designee of an agency (other than of a Federal agency) referred to in the preceding subclauses of this clause, if the Commissioner of Social Security deems it appropriate,"],[0,"unless the Commissioner of Social Security determines that selection of a family member would be appropriate."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1383?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1383. Procedure for payment of benefits","tname":"The Public Health and Welfare","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 6928","url":"https://www.law.cornell.edu/uscode/text/42/6928","by":{"1":"26"}},{"t":"case","label":"Abitron Austria GmbH v. Hetronic International, Inc.","cite":"600 U.S. 412","y":2023,"id":"2022/21-1043","sc":1,"sum":"Applying the presumption against extraterritoriality, two provisions of the Lanham Act that prohibit trademark infringement—15 U. S. C. §1114(1)(a) and §1125(a)(1)—are not extraterritorial and extend only to claims where the infringing “use in commerce” is domestic.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"8"}},{"t":"case","label":"Cipollone v. Liggett Group","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Haile v. Pittman","cite":"389 S.E.2d 564","y":1989,"court":"Ga. Ct. App.","url":"https://www.courtlistener.com/c/S.E.2d/389/564/","by":{"2":"14"}},{"t":"case","label":"HollyFrontier Cheyenne Refining, LLC v. Renewable Fuels Ass’n","cite":"594 U.S. 382","y":2021,"id":"2020/20-472","sc":1,"sum":"Under the renewable fuel program’s fuel blending requirements for domestic refineries, a small refinery that previously received a hardship exemption may obtain an “extension” under 42 U. S. C. §7545(o)(9)(B)(i) even if the refinery did not seek a hardship exemption every year after initially doing so.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"17"}},{"t":"case","label":"Jones v. Hendrix","cite":"599 U.S. 465","y":2023,"id":"2022/21-857","sc":1,"sum":"The saving clause in 28 U. S. C. §2255(e) does not allow a prisoner asserting an intervening change in the interpretation of a criminal statute to circumvent the Antiterrorism and Effective Death Penalty Act of 1996’s restrictions on second or successive §2255 motions by filing a habeas petition under §2241.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Lake Country Estates, Inc. v. Tahoe Regional Planing Agency","cite":"440 U.S. 391","y":1979,"id":"1978/77-1327","sc":1,"sum":"California and Nevada entered into a Compact, later consented to by Congress, to create respondent Tahoe Regional Planning Agency (TRPA) to coordinate and regulate development in the Lake Tahoe Basin resort area and to conserve its natural resources. The Compact authorized TRPA to adopt and enforce a regional plan for land use, transportation, conservation, recreation, and public services. Petitioners, Basin …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"7"}},{"t":"case","label":"National Ass’n of Manufacturers v. DOD","cite":"583 U.S. 109","y":2018,"url":"https://supreme.justia.com/cases/federal/us/583/109/","sc":1,"by":{"2":"23"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Sheridan v. United States","cite":"487 U.S. 392","y":1988,"id":"1987/87-626","sc":1,"sum":"Petitioners' claim is not barred by § 2680(h). Although the words \"any claims arising out of\" an assault or battery are broad enough to bar all claims based entirely on an assault or battery, in at least some situations the fact that injury was directly caused by an assault or battery will not preclude liability against the Government for negligently allowing the assault to occur. Cf. United States v. Muniz, 374 U. …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13–14"}},{"t":"case","label":"Smith v. United States","cite":"507 U.S. 197","y":1993,"id":"1992/91-1538","sc":1,"sum":"The FTCA does not apply to tortious acts or omissions occurring in Antarctica. The ordinary meaning of \"foreign country\" includes Antarctica, even though it has no recognized government. If this were not so, § 1346(b)-which waives sovereign immunity for certain torts committed \"under circumstances where the United States, if a private person, would be liable... in accordance with the law of the place where the act …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Torres-Estrada v. Cases","cite":"88 F.4th 14","y":2023,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.4th/88/14/","by":{"2":"12"}},{"t":"case","label":"United States v. Hayes","cite":"555 U.S. 415","y":2009,"id":"2008/07-608","sc":1,"sum":"With Justice Ruth Bader Ginsburg writing for the majority and joined by Justice John Paul Stevens, Justice Anthony M. Kennedy, Justice David H. Souter, Justice Stephen G. Breyer, and Justice Samuel A. Alito, and joined in part by Justice Clarence Thomas, the Court reasoned that the language of the Gun Control Act suggested that the predicate offense statute need only include \"the use of force\" as an element of the crime and need not include a \"domestic relationship\" as an additional element.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Warger v. Shauers","cite":"574 U.S. 40","y":2014,"id":"2014/13-517","sc":1,"sum":"The Court held that the Federal Rule of Evidence 606(b) bars the testimony of a juror regarding statements made during deliberations for the purpose of showing alleged dishonesty by a prospective juror during jury selection.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Wyatt v. Cole","cite":"504 U.S. 158","y":1992,"id":"1991/91-126","sc":1,"sum":"With the assistance of respondent Robbins, an attorney, respondent Cole filed a complaint under the Mississippi replevin statute against his partner, petitioner Wyatt. After Cole refused to comply with a state court order to return to Wyatt property seized under the statute, Wyatt brought suit in the Federal District Court under 42 U. S. C. § 1983, challenging the state statute's constitutionality and seeking …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 981","url":"https://www.law.cornell.edu/uscode/text/18/981","subs":["(b)"],"by":{"2":"21"}},{"t":"usc","label":"19 U.S.C. § 1605","url":"https://www.law.cornell.edu/uscode/text/19/1605","by":{"2":"21"}},{"t":"rule","label":"Fed. R. Crim. P. 41","url":"https://www.law.cornell.edu/rules/frcrmp/rule_41","subs":["(e)(2)(A)"],"by":{"2":"12"}}]};